// Valid parentheses: O(n) time, O(n) space
function isValid(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const stack = [];
  for (const ch of s) {
    if (ch in pairs) {
      if (stack.pop() !== pairs[ch]) return false;
    } else {
      stack.push(ch);
    }
  }
  return stack.length === 0;
}

// Monotonic stack: days until a warmer temperature. O(n)
function dailyTemperatures(temps) {
  const answer = new Array(temps.length).fill(0);
  const stack = []; // indexes, temperatures decreasing
  for (let i = 0; i < temps.length; i++) {
    while (stack.length && temps[stack[stack.length - 1]] < temps[i]) {
      const j = stack.pop();
      answer[j] = i - j;
    }
    stack.push(i);
  }
  return answer;
}

// Queue from two stacks: amortised O(1)
class MyQueue {
  constructor() { this.inbox = []; this.outbox = []; }
  push(x) { this.inbox.push(x); }
  #shift() { if (!this.outbox.length) while (this.inbox.length) this.outbox.push(this.inbox.pop()); }
  pop() { this.#shift(); return this.outbox.pop(); }
  peek() { this.#shift(); return this.outbox[this.outbox.length - 1]; }
  empty() { return !this.inbox.length && !this.outbox.length; }
}

