// Valid parentheses: O(n) time, O(n) space
static boolean isValid(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') stack.push(c);
        else {
            if (stack.isEmpty()) return false;
            char open = stack.pop();
            if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) return false;
        }
    }
    return stack.isEmpty();
}

// Daily temperatures with a monotonic stack. O(n)
vector<int> dailyTemperatures(const vector<int>& temps) {
    vector<int> answer(temps.size(), 0);
    stack<int> st; // indexes, temperatures decreasing
    for (int i = 0; i < (int)temps.size(); i++) {
        while (!st.empty() && temps[st.top()] < temps[i]) {
            int j = st.top(); st.pop();
            answer[j] = i - j;
        }
        st.push(i);
    }
    return answer;
}

class ListNode {
  constructor(val, next = null) { this.val = val; this.next = next; }
}

// Reverse: O(n) time, O(1) space
function reverseList(head) {
  let prev = null, curr = head;
  while (curr) {
    const next = curr.next; // save the rest first
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  return prev;
}

// Cycle detection (Floyd): O(n) time, O(1) space
function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

// Merge two sorted lists using a dummy node: O(m + n)
function mergeTwoLists(a, b) {
  const dummy = new ListNode(0);
  let tail = dummy;
  while (a && b) {
    if (a.val <= b.val) { tail.next = a; a = a.next; }
    else { tail.next = b; b = b.next; }
    tail = tail.next;
  }
  tail.next = a ?? b;
  return dummy.next;
}

