def reverse_list(head):
    prev, curr = None, head
    while curr:
        nxt = curr.next   # save the rest first
        curr.next = prev
        prev, curr = curr, nxt
    return prev

# Cycle detection (Floyd): O(n) time, O(1) space
def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

# Merge two sorted lists using a dummy node: O(m + n)
def merge_two_lists(a, b):
    dummy = tail = ListNode()
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b
    return dummy.next

